package enrich

import (
	"context"
	"sync"
	"time"

	"github.com/mellifera/mellifera/internal/store"
)

// reenrichOwner is the lease owner tag the sweep claims rows under — distinct
// from the workers' owner so a leaked lease is attributable in debugging.
const reenrichOwner = "reenrich"

// reenrichRetryDelay spaces the sweep's single bounded retry pass from the
// first pass (enrichment D-2: a worker's persistRow window is short, so one
// short-delay re-attempt covers the resurrection hazard without spinning).
const reenrichRetryDelay = 20 * time.Millisecond

// ReenrichSource is the explicit, operator-triggered refresh of ONE plugin's
// namespace over the scoped rows (enrichment D-1/D-2 — the change's only +1
// exported symbol). Empty rowIDs scopes the whole library: every row carrying
// the plugin's namespace or a within-cooldown ledger row for the plugin (the
// rows a refresh can change — a row with neither has nothing to refresh).
// Explicit rowIDs scope exactly the named rows — plus, when a named row is a
// SERIES row, that series' episode items (the routed episode-title side-output
// must refresh with its series or it goes stale forever; episode-titles D6).
//
// Per scoped row, under that row's own non-blocking lease (the workers' lease
// primitive — a held row is NEVER stripped mid-flight, because persistRow on
// the worker path is unconditional and would silently resurrect an unleased
// strip): purge doc.sources.<pluginID>, the _provenance entries with
// plugin_id == pluginID, and the _view entries with source == pluginID; clear
// the plugin's ledger row (the explicit-action cooldown bypass — automatic
// paths never bypass); register the (row, plugin) pair as explicitly-triggered
// so its terminal failure cools flat (explicitSet, enrichment 3.4). The purge
// NEVER touches doc.identifiers (the id anchor, enrichment D-4) or any other
// plugin's namespace, and title_overrides is structurally unreachable (a
// separate control table).
//
// Rows the sweep actually stripped (the namespace was present) flip to pending
// via the refresh transition (enrichment D-3); rows with nothing to strip keep
// their status, so pending stays a truthful will-fetch signal. Lease-held rows
// are re-attempted once after reenrichRetryDelay — the one bounded retry pass
// (enrichment D-2); rows that stay held are counted as deferred and keep their
// namespace intact. The sweep finishes with Notify(libraryID) so the unchanged
// derivation gates re-derive the stripped pairs — no predicate extension, no
// new trigger machinery.
//
// stripped counts scoped rows processed to completion (namespace removed, or
// nothing to remove for an explicitly named row); deferred counts rows that
// stayed lease-held through the retry pass. Rows deleted between scope
// resolution and strip are counted as neither. A store read failure aborts
// scope resolution with the error; per-row failures soft-fail (skipped).
func (q *Queue) ReenrichSource(ctx context.Context, libraryID int64, pluginID string, rowIDs ...string) (stripped, deferred int, err error) {
	scope, err := q.reenrichScope(ctx, libraryID, pluginID, rowIDs)
	if err != nil {
		return 0, 0, err
	}
	if len(scope) == 0 {
		return 0, 0, nil
	}
	stripped, held := q.stripPass(ctx, scope, pluginID)
	if len(held) > 0 { // the one bounded retry pass (enrichment D-2)
		select {
		case <-ctx.Done():
			return stripped, len(held), ctx.Err()
		case <-time.After(reenrichRetryDelay):
		}
		retried, stillHeld := q.stripPass(ctx, held, pluginID)
		stripped += retried
		deferred = len(stillHeld)
	}
	if q.running.Load() { // a stopped queue has no work channel; a Notify feeder would block forever
		q.Notify(ctx, libraryID)
	}
	return stripped, deferred, nil
}

// reenrichScope resolves the sweep's row set: explicit rowIDs verbatim (grown
// by the named series rows' episode items — scopeWithEpisodes), or — for a
// whole-library sweep — every item and series row of the library carrying the
// plugin's namespace or a within-cooldown ledger row for it (a sweep needs no
// cascade: it already covers every item and series row carrying the
// namespace).
func (q *Queue) reenrichScope(ctx context.Context, libraryID int64, pluginID string, rowIDs []string) ([]string, error) {
	if len(rowIDs) > 0 {
		return q.scopeWithEpisodes(ctx, rowIDs), nil
	}
	items, err := q.allItems(ctx, libraryID)
	if err != nil {
		return nil, err
	}
	seriesRows, err := q.allSeries(ctx, libraryID)
	if err != nil {
		return nil, err
	}
	idx, err := q.fetchFailureIndex(ctx)
	if err != nil {
		return nil, err
	}
	nowt := now()
	scope := make([]string, 0)
	for _, it := range items {
		if hasNamespace(decodeDoc(it.Document), pluginID) || inCooldown(idx, it.ID, pluginID, nowt) {
			scope = append(scope, it.ID)
		}
	}
	for _, sr := range seriesRows {
		if hasNamespace(decodeDoc(sr.Document), pluginID) || inCooldown(idx, sr.ID, pluginID, nowt) {
			scope = append(scope, sr.ID)
		}
	}
	return scope, nil
}

// scopeWithEpisodes grows an explicit rowID scope: a named SERIES row also
// scopes its episode items (QueryItemsBySeries — the same directory-backed
// read the routing uses; a routed sources.<plugin> on an episode doc is the
// series run's side-output and must refresh with the series strip or it goes
// stale forever, episode-titles D6 — the pair gate skips on namespace
// presence, so nothing else would ever rewrite it). A row id naming an item
// (or a gone row) cascades nothing — item-only explicit scopes stay exactly
// as before; a file-backed series cascades nothing (the routing never routes
// episode docs onto one). The strip itself is the unchanged per-row purge;
// this only widens WHO is scoped. Order-preserving, deduplicated (a caller
// naming both a series and one of its episodes strips each row once).
func (q *Queue) scopeWithEpisodes(ctx context.Context, rowIDs []string) []string {
	scope := make([]string, 0, len(rowIDs))
	seen := make(map[string]struct{}, len(rowIDs))
	keep := func(id string) {
		if _, dup := seen[id]; !dup {
			seen[id] = struct{}{}
			scope = append(scope, id)
		}
	}
	for _, id := range rowIDs {
		keep(id)
		sr, err := q.deps.Store.GetSeries(ctx, id)
		if err != nil {
			continue // an item id (or a gone row): no cascade
		}
		if backingOf(decodeDoc(sr.Document)) != store.SeriesBackingDirectory {
			continue // a file-backed series has no routed episode docs to cascade
		}
		eps, err := q.deps.Store.QueryItemsBySeries(ctx, sr, store.SeriesBackingDirectory)
		if err != nil {
			continue // best-effort: the named series row itself stays scoped
		}
		for _, ep := range eps {
			keep(ep.ID)
		}
	}
	return scope
}

// stripPass runs one strip attempt over the given rows and returns how many it
// completed plus the ids it could not attempt (a live lease held).
func (q *Queue) stripPass(ctx context.Context, ids []string, pluginID string) (stripped int, held []string) {
	for _, id := range ids {
		if !q.leases.acquire(id, reenrichOwner, q.cfg.LeaseTTL) {
			held = append(held, id) // a worker owns the row — never strip mid-flight (enrichment D-2)
			continue
		}
		row, err := q.loadRow(ctx, id)
		if err != nil {
			q.leases.release(id)
			continue // the row is gone (or unreadable) between scope and strip: nothing to strip
		}
		doc := decodeDoc(row.doc)
		removed := stripSource(doc, pluginID)
		if removed { // flip ONLY rows actually stripped (enrichment D-3); elsewhere the flip is illegal
			stripped++
			if next, terr := nextState(row.status, evRefresh); terr == nil {
				row.status = next
			}
		}
		q.registerExplicit(id, pluginID) // this run is explicit: its terminal failure cools flat (enrichment 3.4)
		q.storeWrite(func() error { return q.deps.Store.ClearFailure(ctx, id, pluginID) })
		q.persistRow(ctx, row, row.status, doc)
		q.leases.release(id)
	}
	return stripped, held
}

// stripSource purges one plugin's three document regions in place — its
// sources.<pluginID> namespace, the _provenance entries it authored
// (plugin_id), and the _view entries it backs (source) — leaving
// doc.identifiers and every other plugin's entries untouched. Reports whether
// the plugin's namespace was present (the sweep's only status-flip signal).
func stripSource(doc map[string]any, pluginID string) bool {
	removed := false
	if sources, ok := doc["sources"].(map[string]any); ok {
		if _, exists := sources[pluginID]; exists {
			delete(sources, pluginID)
			removed = true
		}
	}
	if prov, ok := doc["_provenance"].(map[string]any); ok {
		for field, entry := range prov {
			if e, ok := entry.(map[string]any); ok {
				if pid, _ := e["plugin_id"].(string); pid == pluginID {
					delete(prov, field)
				}
			}
		}
	}
	if view, ok := doc["_view"].(map[string]any); ok {
		for field, entry := range view {
			if e, ok := entry.(map[string]any); ok {
				if src, _ := e["source"].(string); src == pluginID {
					delete(view, field)
				}
			}
		}
	}
	return removed
}

// explicitSet is the queue's process-lifetime ledger of explicitly-refreshed
// (row, plugin) pairs (enrichment 3.4). The sweep registers a pair on its
// strip; the dispatch consumes the entry when it records that pair's terminal
// ledger row, so an explicitly-triggered run cools at the FLAT schedule
// (explicitCooldown) while automatic runs keep the standard doubling. In-memory
// and best-effort by design: a crash mid-sweep loses the marker, and the worst
// case is one standard-schedule cooldown — never a loop (the sweep cleared the
// ledger row anyway).
type explicitSet struct {
	mu    sync.Mutex
	pairs map[coolKey]struct{}
}

// newExplicitSet constructs an empty marker set.
func newExplicitSet() *explicitSet {
	return &explicitSet{pairs: make(map[coolKey]struct{})}
}

// registerExplicit marks (rowID, pluginID) as explicitly-triggered.
func (q *Queue) registerExplicit(rowID, pluginID string) {
	q.explicit.mu.Lock()
	q.explicit.pairs[coolKey{rowID, pluginID}] = struct{}{}
	q.explicit.mu.Unlock()
}

// takeExplicit consumes the pair's marker: true iff the pair's next terminal
// ledger row belongs to an explicitly-triggered run.
func (q *Queue) takeExplicit(rowID, pluginID string) bool {
	q.explicit.mu.Lock()
	defer q.explicit.mu.Unlock()
	k := coolKey{rowID, pluginID}
	_, ok := q.explicit.pairs[k]
	if ok {
		delete(q.explicit.pairs, k)
	}
	return ok
}
